CREATE TABLE `kunlik_hisobot` (
  `id` int NOT NULL AUTO_INCREMENT,
  `sana` date NOT NULL,
  `jami_savdo` int NOT NULL DEFAULT '0',
  `jami_chegirma` int NOT NULL DEFAULT '0',
  `jami_bonus` int NOT NULL DEFAULT '0',
  `jami_bemorlar` int NOT NULL DEFAULT '0',
  `jami_naqd` int NOT NULL DEFAULT '0',
  `jami_karta` int NOT NULL DEFAULT '0',
  `jami_click` int NOT NULL DEFAULT '0',
  `jami_qarz` int NOT NULL DEFAULT '0',
  `naqd_count` int NOT NULL DEFAULT '0',
  `karta_count` int NOT NULL DEFAULT '0',
  `click_count` int NOT NULL DEFAULT '0',
  `qarz_count` int NOT NULL DEFAULT '0',
  `yangilangan_sana` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `sana` (`sana`),
  KEY `idx_sana` (`sana`)
