--
-- Table structure for table `orders`
--

DROP TABLE IF EXISTS `orders`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `orders` (
  `id` int NOT NULL AUTO_INCREMENT,
  `bemor_id` int NOT NULL,
  `vrach_id` int DEFAULT NULL,
  `vrach_nomi` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `filial_id` int DEFAULT NULL,
  `sample_id` varchar(12) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `guruh` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `chegirma_percent` int DEFAULT '0',
  `subtotal` int DEFAULT NULL,
  `discount` int DEFAULT NULL,
  `total` int DEFAULT NULL,
  `payment_type` enum('naqd','karta','click','qarz') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'naqd',
  `paid_amount` int DEFAULT NULL,
  `sana_vaqt` datetime DEFAULT CURRENT_TIMESTAMP,
  `status` enum('new','paid','cancelled') COLLATE utf8mb4_unicode_ci DEFAULT 'new',
  `namuna_hajmi_turi` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `chashka_turi` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `krovat_raqami` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `suyultirilgan` tinyint(1) NOT NULL DEFAULT '0',
  `boyalgan` tinyint(1) NOT NULL DEFAULT '0',
  `namuna_tayyorlash` tinyint(1) NOT NULL DEFAULT '0',
  `favqulodda_vaziyat` tinyint(1) NOT NULL DEFAULT '0',
  `cycle_day` tinyint DEFAULT NULL,
  `cycle_note` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `chegirma_sababi` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_by` int DEFAULT NULL,
  `updated_by` int DEFAULT NULL,
  `deleted_by` int DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  `delete_reason` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `sample_id` (`sample_id`),
  KEY `bemor_id` (`bemor_id`),
  KEY `filial_id` (`filial_id`),
  KEY `vrach_id` (`vrach_id`),
  CONSTRAINT `orders_ibfk_1` FOREIGN KEY (`bemor_id`) REFERENCES `bemorlar` (`id`),
  CONSTRAINT `orders_ibfk_2` FOREIGN KEY (`filial_id`) REFERENCES `filiallar` (`id`) ON DELETE SET NULL,
  CONSTRAINT `orders_ibfk_3` FOREIGN KEY (`vrach_id`) REFERENCES `vrachlar` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=1640 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

