--
-- Table structure for table `tahlil_inventory`
--

DROP TABLE IF EXISTS `tahlil_inventory`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tahlil_inventory` (
  `id` int NOT NULL AUTO_INCREMENT,
  `tahlil_id` int NOT NULL,
  `qoldiq` int NOT NULL DEFAULT '0',
  `minimal_limit` int DEFAULT '10',
  `is_unlimited` tinyint(1) DEFAULT '0' COMMENT 'Cheksiz tahlil (zamburug, mazok, umumiy qon va h.k.)',
  `upokovka_soni` int DEFAULT NULL COMMENT 'Bir pachkada nechta test',
  `oxirgi_kirim_sana` datetime DEFAULT NULL,
  `oxirgi_chiqim_sana` datetime DEFAULT NULL,
  `izoh` text,
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `tahlil_id` (`tahlil_id`),
  KEY `idx_qoldiq` (`qoldiq`),
  KEY `idx_minimal_limit` (`minimal_limit`),
  CONSTRAINT `tahlil_inventory_ibfk_1` FOREIGN KEY (`tahlil_id`) REFERENCES `tahlillar` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=6918 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

