DROP TABLE IF EXISTS `tahlil_ko_rsatkichlar`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tahlil_ko_rsatkichlar` (
  `id` int NOT NULL AUTO_INCREMENT,
  `tahlil_id` int DEFAULT NULL,
  `tahlil_nomi` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `ko_rsatkich_nomi` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `birlik` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `norma` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `tartib_raqami` int DEFAULT '0',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_korsatkich` (`tahlil_nomi`,`ko_rsatkich_nomi`),
  KEY `idx_tahlil` (`tahlil_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
