--
-- Table structure for table `tahlil_transactions`
--

DROP TABLE IF EXISTS `tahlil_transactions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tahlil_transactions` (
  `id` int NOT NULL AUTO_INCREMENT,
  `tahlil_id` int NOT NULL,
  `transaction_type` enum('kirim','chiqim','qaytarish','inventarizatsiya') NOT NULL,
  `upokovka_soni` int DEFAULT NULL COMMENT 'Nechta pachka kirim qilingan',
  `miqdor` int NOT NULL COMMENT 'Jami dona soni',
  `order_id` int DEFAULT NULL COMMENT 'Qaysi buyurtma uchun chiqim',
  `sana` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `izoh` text,
  `created_by` int DEFAULT NULL COMMENT 'Kim kiritgan',
  PRIMARY KEY (`id`),
  KEY `order_id` (`order_id`),
  KEY `created_by` (`created_by`),
  KEY `idx_tahlil_id` (`tahlil_id`),
  KEY `idx_sana` (`sana`),
  KEY `idx_transaction_type` (`transaction_type`),
  CONSTRAINT `tahlil_transactions_ibfk_1` FOREIGN KEY (`tahlil_id`) REFERENCES `tahlillar` (`id`) ON DELETE CASCADE,
  CONSTRAINT `tahlil_transactions_ibfk_2` FOREIGN KEY (`order_id`) REFERENCES `orders` (`id`) ON DELETE SET NULL,
  CONSTRAINT `tahlil_transactions_ibfk_3` FOREIGN KEY (`created_by`) REFERENCES `foydalanuvchilar` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=4080 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

